"use strict";
// Export the EXACT portrait generated by the existing 3D avatar.
// Runs in CI; the production chat should serve this still without WebGL work.
const fs=require("node:fs");
const {chromium}=require("playwright");
(async()=>{
 const browser=await chromium.launch({headless:true,args:["--no-sandbox","--enable-unsafe-swiftshader"]});
 try{
  const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1});
  const errors=[];
  page.on("pageerror",e=>errors.push(e.message));
  await page.goto("http://127.0.0.1:4177/bilik-antara.html",{waitUntil:"domcontentloaded",timeout:30000});
  await page.waitForFunction(()=>document.documentElement.classList.contains("chat-portrait-ready"),null,{timeout:65000});
  const portrait=await page.evaluate(()=>{
   const css=document.documentElement.style.getPropertyValue("--ai-chat-portrait");
   return /data:image\/png;base64,([a-zA-Z0-9+/=]+)/.exec(css)?.[1]||"";
  });
  if(!portrait)throw Error("3D avatar did not expose a PNG portrait; "+errors.join("; "));
  const image=Buffer.from(portrait,"base64");
  if(image.length<1000||image.length>450000||image.subarray(0,8).toString("hex")!=="89504e470d0a1a0a")throw Error("Generated portrait PNG is invalid");
  const size=image.readUInt32BE(16),height=image.readUInt32BE(20);
  if(size!==160||height!==160)throw Error("Unexpected 3D portrait size "+size+"x"+height);
  fs.writeFileSync("audit-avatar-portrait.png",image);
  console.log("[portrait] exact 3D avatar frame extracted: "+size+"x"+height+", "+image.length+" bytes; no redesign");
 }finally{await browser.close();}
})().catch(e=>{console.error("[portrait] "+(e.stack||e));process.exitCode=1;});
